package com.securevault.controller;
import com.securevault.entity.*;import com.securevault.repository.UserRepository;import com.securevault.service.CredentialService;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/vault") @CrossOrigin(origins="http://localhost:5173") public class VaultController{private final CredentialService service;private final UserRepository users;public VaultController(CredentialService s,UserRepository u){service=s;users=u;}private User u(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}@PostMapping("/credentials")public ResponseEntity<?> add(@jakarta.validation.Valid @RequestBody Credential c,Authentication a){return ResponseEntity.ok(service.addCredential(c,u(a)));}@GetMapping("/credentials")public Object list(Authentication a){return service.getUserCredentials(u(a));}@GetMapping("/advanced/search")public Object search(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false)Boolean favorite,Authentication a){return service.search(u(a),q,category,favorite);}@PutMapping("/credentials/{id}")public ResponseEntity<?> update(@PathVariable Long id,@jakarta.validation.Valid @RequestBody Credential c,Authentication a){try{return ResponseEntity.ok(service.updateCredential(id,c,u(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(e.getMessage());}}@DeleteMapping("/credentials/{id}")public ResponseEntity<?> delete(@PathVariable Long id,Authentication a){try{service.deleteCredential(id,u(a));return ResponseEntity.ok(Map.of("message","Credential deleted"));}catch(RuntimeException e){return ResponseEntity.badRequest().body(e.getMessage());}}@PatchMapping("/credentials/{id}/favorite")public Object favorite(@PathVariable Long id,Authentication a){return service.favorite(id,u(a));}}
